$pages = [
 'about-us'=>['About Seleneith', <<<'HTML'
<div class="brand-story-page">
 <figure class="brand-story-hero"><img src="/wp-content/themes/seleneith/assets/seleneith-story-self-moment.jpg" alt="Woman wearing a delicate pendant necklace in a quiet morning moment"><figcaption>Editorial imagery illustrates the Seleneith point of view; it does not depict a specific item for sale.</figcaption></figure>
 <header class="brand-story-intro"><p class="brand-story-kicker">A note from Seleneith</p><p class="brand-story-lead">Jewelry for the moments that make you, you.</p><p>Some moments are milestones. Others are small and entirely your own: a fresh start, a deep breath, the familiar feeling of getting dressed in a way that feels right. We believe jewelry can be part of those moments—not because it changes who you are, but because it can reflect what already matters to you.</p></header>
 <section class="brand-story-philosophy"><p class="brand-story-kicker">Our point of view</p><h2>Meaning is personal. Style should be, too.</h2><div class="brand-story-values"><article><span>01</span><h3>No occasion required</h3><p>A piece can mark a celebration, a thoughtful gift, or an ordinary Tuesday. You decide what it means.</p></article><article><span>02</span><h3>Your way, always</h3><p>Wear one detail on its own, layer pieces together, or change your look whenever you like. There is no single right way.</p></article><article><span>03</span><h3>Choose for yourself</h3><p>Personal style is not a set of rules to follow. It is a small, everyday way to show up as you are.</p></article></div></section>
 <section class="brand-story-image-text"><figure><img src="/wp-content/themes/seleneith/assets/seleneith-story-everyday-style.jpg" alt="Woman wearing a simple necklace and hoop earrings while taking a quiet pause"><figcaption>Editorial image; jewelry shown is illustrative, not a product listing.</figcaption></figure><div><p class="brand-story-kicker">A little room to be yourself</p><h2>Not a new you. Just more of you.</h2><p>Life asks us to move between many roles and responsibilities. A familiar detail can be a gentle reminder that your own preferences belong in the picture, too. Seleneith is here for that feeling: personal, unforced, and yours to define.</p></div></section>
 <section class="brand-story-clear"><p class="brand-story-kicker">Thoughtful choices, clear details</p><h2>Feel good about what you choose.</h2><p>Each piece is different, so check its product page for the listed materials, measurements, available options and care notes before ordering. We want the details that help you decide to be easy to find.</p><p>We ship from China to the United States, Canada and Australia. Shipping costs, delivery estimates and return conditions are explained in our store policies. For a return, send a request through our return form; our team reviews it and replies by email within 48 hours.</p><div class="information-links"><a href="/collections/all-products-collection/">Explore the collection</a><a href="/pages/shipping-policy/">Shipping information</a><a href="/pages/return-policy/">Returns</a><a href="/pages/contact/">Contact us</a></div></section>
</div>
HTML],
 'a-letter-from-us'=>['A Letter From Seleneith','<p>Welcome to Seleneith. We believe jewelry can hold a meaning that is entirely your own — a small reminder, a quiet celebration, or simply a detail that feels like you.</p><p>You do not need to wait for a special occasion to choose something meaningful. Wear it your way, give it with care, and let the story be yours.</p><p>Thank you for being here. — Seleneith</p><p><a href="/pages/about-us/">Read our point of view</a> · <a href="/collections/all-products-collection/">Explore the collection</a></p>'],
 'faq'=>['Frequently Asked Questions', <<<'HTML'
<details open><summary>Where do you ship?</summary><p>We ship from China to the United States, Canada and Australia. The store is in English. Select your country in the site menu to view USD, CAD or AUD prices.</p></details>
<details><summary>How much does shipping cost?</summary><p>Orders with a merchandise subtotal below the US$59 equivalent after discounts have standard shipping of US$9.90 to the United States, US$12.90 to Canada, or US$15.90 to Australia. Orders of US$59 equivalent or more receive free standard shipping. Taxes and shipping do not count towards the threshold. Checkout shows the converted amount in your selected currency.</p><p><a href="/pages/shipping-policy/">Read the Shipping Policy</a></p></details>
<details><summary>When will my order arrive?</summary><p>Estimated delivery is 12–25 business days from ordering to receipt, including processing and transport. Business days exclude weekends and public holidays. Customs, peak periods and remote destinations can cause delays; this is an estimate, not a guaranteed arrival date.</p></details>
<details><summary>How can I pay?</summary><p>Payments are processed through PayPal. The payment options available for your order appear at checkout. You may be redirected to PayPal to complete payment. Check the currency and total before submitting your order.</p></details>
<details><summary>Could there be import charges?</summary><p>Import duties, destination taxes or carrier handling fees may apply unless expressly collected at checkout. Read the charges shown at checkout and our <a href="/pages/shipping-policy/">Shipping Policy</a> before ordering. Shipping charges are not a promise of duty-paid delivery.</p></details>
<details><summary>How do I choose a color, size or style?</summary><p>Select the available options on the product page before adding the item to your bag. The selected option can affect the price and availability. If you need a measurement or material detail that is not listed, <a href="/pages/contact/">contact us</a> before ordering.</p></details>
<details><summary>How do I use my 10% discount code?</summary><p>Request your code through the email offer form, then enter it in the coupon field at checkout. One code is issued per email address, can be redeemed once and expires after 30 days. Use the same email address at checkout. The code cannot be combined with other coupons.</p></details>
<details><summary>Where can I check my order?</summary><p>Use <a href="/pages/track-my-order/">Track My Order</a> with your order number and billing email, or sign in to <a href="/my-account/orders/">your account</a>. For help with delivery tracking, email us with your order number.</p></details>
<details><summary>Can I return an item or report a problem?</summary><p>Use our <a href="https://returns.seleneith.com/">return request form</a> within 14 days of delivery for a voluntary return. We will review your request and reply by email within 48 hours. Conditions apply, and buyers pay return shipping for non-defective returns. Contact us for instructions before sending anything back. For a damaged, defective or incorrect item, email us promptly so we can help.</p><p>A 100-day manufacturing-defect warranty applies in addition to statutory rights. Read the <a href="/pages/return-policy/">Return Policy</a> for conditions and the refund process.</p></details>
<details><summary>How do I contact Seleneith?</summary><p>Email <a href="mailto:seleneith@163.com">seleneith@163.com</a>. Include your order number for an existing order, or the product name and options for a product question.</p></details>
HTML],
 'jewelry-care'=>['Jewelry Care','<h2>Keep your pieces looking their best</h2><p>Store pieces separately in a dry place. Wipe gently with a soft cloth after use. Avoid abrasive cleaners and direct contact with perfume, lotions and household chemicals.</p><p>Care requirements depend on the material and finish. Check the materials listed on each product page; do not assume every piece is waterproof. If you are unsure about a finish or stone, <a href="/pages/contact/">contact us</a> before cleaning it.</p>'],
